import{_ as d,o as a,c as r,a6 as e}from"./chunks/framework.D9iQZIpB.js";const u=JSON.parse('{"title":"排除与缺口","description":"范围排除项、争议来源标注、采集排除原因与报告自述的信息缺口","frontmatter":{"title":"排除与缺口","description":"范围排除项、争议来源标注、采集排除原因与报告自述的信息缺口"},"headers":[],"relativePath":"excluded.md","filePath":"excluded.md","lastUpdated":null}'),o={name:"excluded.md"};function l(n,t,h,i,s,c){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="排除与缺口" tabindex="-1">排除与缺口 <a class="header-anchor" href="#排除与缺口" aria-label="Permalink to &quot;排除与缺口&quot;">​</a></h1><p>本页集中说明<strong>为什么有些内容不在资料库中</strong>。所有排除都注明原因，未获取的信息如实留空，不作推测补全。</p><h2 id="一、不符合「完整公开」标准的范围排除-照录报告第-7-章" tabindex="-1">一、不符合「完整公开」标准的范围排除（照录报告第 7 章） <a class="header-anchor" href="#一、不符合「完整公开」标准的范围排除-照录报告第-7-章" aria-label="Permalink to &quot;一、不符合「完整公开」标准的范围排除（照录报告第 7 章）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对象</th><th>排除原因</th></tr></thead><tbody><tr><td>广义青城派养生术</td><td>核心口诀仍未完整公开；青城丹法「诀中诀」久已不传，玄门太极长生功最后一节「神元功」自宋以后失传。已出版的《青城太极养生》《跟掌门学养生》为改良简化版，并非完整秘传体系。王庆余筋经内丹功属青城系统内<strong>独立公开的支脉</strong>，已单列</td></tr><tr><td>少林洗髓经</td><td>真本已失传，现存版本均为清代托名编撰（1893 年周述官《增演易筋洗髓内功图说》一系），属托名文本而非秘传公开</td></tr><tr><td>马王堆导引术</td><td>源自 1973 年长沙马王堆三号汉墓出土帛画《导引图》，现行功法为学者依据帛画的<strong>考古重建</strong>，不存在「秘传—公开」的传承过程；仅作为标准化体系对照出现</td></tr><tr><td>武当太和门《赤凤髓》</td><td>仍处「首次公开传授」的商业化传功阶段，未形成完整公开体系</td></tr></tbody></table><blockquote><p>此外，多数传统门派（各派太极拳、易筋经流派）仅公开基础功法，核心口诀仍半保密，不纳入「完整公开」对象。</p></blockquote><h2 id="二、可靠性不足或存在争议的来源-照录报告第-7-章" tabindex="-1">二、可靠性不足或存在争议的来源（照录报告第 7 章） <a class="header-anchor" href="#二、可靠性不足或存在争议的来源-照录报告第-7-章" aria-label="Permalink to &quot;二、可靠性不足或存在争议的来源（照录报告第 7 章）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>说法 / 来源</th><th>处理</th></tr></thead><tbody><tr><td>大雁气功「成功申办非遗」</td><td>仅见于抖音来源，未获官方名录证实；本站<strong>仅采信</strong>龙港市 2025 年第三批市级非遗名录记录</td></tr><tr><td>金刚长寿功 2021 / 2022 修订版</td><td>张至顺道长生前未认可，对内容作了大量删改；资料索引以 2013 年深圳报业集团出版社原版为准</td></tr><tr><td>「中国大雁气功总部」名义</td><td>存在传承争议，原北京大雁气功总站已不存在；相关公司已吊销、商标已无效</td></tr><tr><td>B 站冒用「黄中宫」名义的账号</td><td>账号自述非官方，不作权威来源</td></tr><tr><td>回春功网络传承体系</td><td>存在多个自称流派，报告建议以上海市气功研究所官方传承点为准</td></tr><tr><td>千峰先天派</td><td>无统一官方网站，各支脉自行运营；高阶功法不轻授文本自修者</td></tr></tbody></table><h2 id="三、本次采集中的排除原因" tabindex="-1">三、本次采集中的排除原因 <a class="header-anchor" href="#三、本次采集中的排除原因" aria-label="Permalink to &quot;三、本次采集中的排除原因&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原因类别</th><th>处理方式</th></tr></thead><tbody><tr><td>平台服务条款与著作权限制（B 站、优酷、抖音、爱奇艺、西瓜视频、YouTube、网易公开课、央视视频）</td><td><strong>不下载音视频文件</strong>，仅保留原始链接与状态说明</td></tr><tr><td>百科 / 文库 / 公众号图文 / 电子书平台</td><td>权属复杂且无明示开放许可，不保存或转载全文</td></tr><tr><td>学术数据库（知网等）</td><td>需机构授权或付费，仅登记文献题录</td></tr><tr><td>电商、旧书交易、商品动态页</td><td>仅登记书目线索，不抓取页面</td></tr><tr><td>许可未明示的 PDF</td><td>完整下载后标为「已保存·受限」，仅本地核验，站点不提供副本、不转载全文</td></tr><tr><td>HTTP 403（反爬 / 访问控制 / 需登录）</td><td>标注「无法获取」，注明具体状态码，不伪装为资料不存在</td></tr><tr><td>HTTP 404 / 502 / 超时 / 证书或隧道错误</td><td>逐条注明具体错误，不作重试成功假设</td></tr></tbody></table><p>逐条原因见<a href="/hello-world/gongfa-archive/catalog">资料索引</a>与<a href="/hello-world/gongfa-archive/sources">来源说明</a>，完整列表见 <code>data/excluded.json</code>。</p><h2 id="四、报告自述的信息缺口-未获取-不补全" tabindex="-1">四、报告自述的信息缺口（未获取，不补全） <a class="header-anchor" href="#四、报告自述的信息缺口-未获取-不补全" aria-label="Permalink to &quot;四、报告自述的信息缺口（未获取，不补全）&quot;">​</a></h2><ol><li>1985 年湖北科学技术出版社版《大雁功》与 1992 年《大雁功·第二辑》的 ISBN，经多轮检索未获得确切编号。</li><li>各流派学术论文的精确总篇数，因知网检索限制无法统计。</li><li>郭林新气功研究会官网的具体域名、中国古代养生长寿术研究学会的办公地址，未见公开信息。</li><li>七个流派早期「秘传公开」事件（1933 年著书、1959 年著书、1971 年公园授功、1978—1979 年公开、1980 年代初公开、2008 年宫观公开、2013 年出版）均未检索到现代主流媒体的专题报道标题或原始新闻存档。</li><li>报告自述「共涉及 306 个来源链接」，本次从文件正文实际抽取到 <strong>212 个唯一 URL</strong>；两者口径不同（可能为含重复引用的计数或末尾参考文献列表），本站按实际抽取结果列示，<strong>不作推测补全</strong>。</li></ol><h2 id="五、安全与理性提示" tabindex="-1">五、安全与理性提示 <a class="header-anchor" href="#五、安全与理性提示" aria-label="Permalink to &quot;五、安全与理性提示&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">不新增疗效承诺</p><p>各流派资料中的「抗癌」「长寿」「返老还童」等描述，属传承人宣称与早期文献记载，<strong>不等同于现代临床证据</strong>。本站仅作文献编目，不提供功法教学、诊断、治疗或保健建议；患病者应接受规范医疗，并在练习前咨询医生。</p><p>中国健身气功协会的倡议同样适用：警惕自封「大师」「名家」「传人」「正宗」「嫡传」的商业包装与夸大宣传。</p></div><h2 id="六、版权与许可" tabindex="-1">六、版权与许可 <a class="header-anchor" href="#六、版权与许可" aria-label="Permalink to &quot;六、版权与许可&quot;">​</a></h2><p>所有第三方资料的<strong>版权与许可归原权利人</strong>，本站不主张任何权利。已存档的<strong>网页全文与许可未明示的 PDF</strong> 不在站内展示或提供下载；在允许访问与下载范围内采集的图片、公开音视频与样式表，则在<a href="/hello-world/gongfa-archive/media">资源库</a>逐条标注原始出处、来源页、SHA256 与版权状态后展示，仅供本地教学研究核对、不得再分发。</p><p>受平台服务条款或著作权限制的音视频、百科文库、公众号图文、学术数据库全文等一律未下载，仅保留原始链接并标记状态。站点装饰图形均为本项目原创 SVG / CSS 绘制。</p><p>逐条版权与许可说明见<a href="/hello-world/gongfa-archive/sources">来源说明</a>与项目根目录 <code>THIRD_PARTY_LICENSES.md</code>。</p>',18)])])}const g=d(o,[["render",l]]);export{u as __pageData,g as default};
